INSERT INTO public.publications (id, slug, name, description, avatar_url, created_at) VALUES (1, 'devopsxlab-weekly', 'DevOpsXLab Weekly', 'Har hafta: Kubernetes, CI/CD va SRE bo''yicha amaliy maqolalar.', 'https://api.dicebear.com/9.x/shapes/svg?seed=devopsxlab-weekly', '2026-10-05 16:16:20.064809+00') ON CONFLICT DO NOTHING;
INSERT INTO public.publications (id, slug, name, description, avatar_url, created_at) VALUES (2, 'cloud-native-uz', 'Cloud Native UZ', 'O''zbek tilidagi cloud-native hamjamiyat blogi: bulut, Linux va observability.', 'https://api.dicebear.com/9.x/shapes/svg?seed=cloud-native-uz', '2026-10-05 16:16:20.071073+00') ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (41, 'Terraform state: jamoada xavfsiz ishlash qoidalari', 'Terraform''dagi eng og''riqli hodisalar deyarli har doim state fayli bilan bog''liq: ikki kishi bir vaqtda `apply` qildi, kimdir state''ni noutbukida qoldirdi yoki bitta ulkan state''ni yangilash 15 daqiqa oldi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (42, 'Server sekinlashdi: Linux''da birinchi 60 soniya', 'Brendan Gregg''ning mashhur ro''yxatiga asoslangan, kundalik ishda sinalgan tartib. Maqsad — bir daqiqada muammo CPU, xotira, disk yoki tarmoqdami, shuni aniqlash.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (44, 'Go''da graceful shutdown: so''rovlarni yo''qotmasdan to''xtash', 'Har deploy''da bir nechta 502 xato ko''ryapsizmi? Ehtimol, ilovangiz SIGTERM kelganda darhol o''ladi va jarayondagi so''rovlar uziladi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (46, 'Supply chain xavfsizligi: SBOM, imzo va provenance', 'xz-utils voqeasidan keyin "biz faqat o''z kodimizni tekshiramiz" degan yondashuv yetarli emasligi hammaga ayon bo''ldi. Bugun image''ingizning 90 foizi boshqalar yozgan kod.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (50, 'OpenTelemetry bilan tanishuv: trace, metric va log bir joyda', '"Sayt sekin ishlayapti" degan shikoyat keldi. Qaysi servis? Qaysi so''rov? Bazami yoki tashqi API? Uchta alohida vosita va qo''lda vaqt solishtirish bilan bu savollarga javob topish soatlab vaqt oladi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (51, 'Core Web Vitals: LCP, INP va CLS''ni real foydalanuvchida o''lchash', 'Lighthouse noutbukingizda tez Wi-Fi bilan 100 ball ko''rsatadi. Foydalanuvchi esa Andijonda 4G va 3 yillik Android telefonda saytni ochmoqda. Haqiqiy ma''lumot faqat haqiqiy foydalanuvchidan keladi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (52, '1 GB''dan 12 MB''gacha: Go uchun ideal Docker image', '`FROM golang` bilan yig''ilgan image 1 GB atrofida bo''ladi: kompilyator, git, shell va yuzlab paket — barchasi prod''da keraksiz va hujum yuzasini kengaytiradi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (48, 'GitHub Actions pipeline''ni 18 daqiqadan 4 daqiqaga tushirish', 'Sekin CI — bu shunchaki noqulaylik emas. Dasturchilar kichik PR''lar o''rniga katta PR''lar ochishni boshlaydi, chunki har bir push 18 daqiqa kutish demak.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (53, 'GitOps amalda: Argo CD bilan deploy qilish', 'Klasselik CI/CD''da pipeline klasterga `kubectl apply` qiladi. Demak CI''da klasterning admin huquqi bor va klaster holatini faqat oxirgi pipeline log''idan bilish mumkin.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (49, 'AWS hisobini 40% kamaytirgan 7 ta oddiy qadam', 'O''tgan chorakda AWS hisobimiz oyiga 18 ming dollardan oshdi. Hech qanday katta qayta yozishsiz, bir oy ichida uni 10.8 mingga tushirdik. Mana nima qildik.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (55, 'Git''ga sir tushib qoldi. Endi nima qilish kerak?', 'Kimdir `.env` faylini public repo''ga push qildi. Botlar GitHub''dagi yangi commit''larni bir necha **soniyada** skanerlaydi, shuning uchun vaqt hal qiluvchi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (57, 'SSH''ni to''g''ri sozlash: parollardan sertifikatlargacha', 'Ochiq 22-portli yangi VPS internetga chiqqandan keyin o''rtacha 2-3 daqiqada birinchi brute-force urinishlari boshlanadi. `journalctl -u ssh` ga qarang — ishonasiz.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (58, 'Docker Compose bilan lokal muhit: "mening kompyuterimda ishlaydi"ga chek qo''yamiz', 'Yangi dasturchi jamoaga qo''shildi. README''da 23 qadam: Postgres o''rnating, Redis o''rnating, bu versiyani, u portni... Ikkinchi kuni ham loyiha ishga tushmadi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (59, 'Redis kesh: tezlik va noto''g''ri ma''lumot o''rtasidagi muvozanat', '"Kompyuter fanida ikkita qiyin narsa bor: kesh invalidatsiyasi va nomlash." Hazil emas — keshdagi xatolar eng qiyin topiladigan xatolar.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (60, 'Aybdorsiz postmortem: uzilishdan qanday qilib foyda olish mumkin', 'Juma kuni soat 17:40 da to''lov sahifasi 47 daqiqa ishlamadi. Dushanba kuni yig''ilishda birinchi savol: "Kim deploy qildi?" Bu — noto''g''ri savol.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (61, 'Platform engineering: DevOps jamoasi tiket navbatiga aylanmasligi uchun', 'DevOps jamoamizda 140 ta ochiq tiket bor edi: "yangi bucket kerak", "staging''ga namespace bering", "pipeline''ni sozlab bering". Har bir jamoa 3-5 kun kutardi. "DevOps" madaniyat emas, alohida bo''limga aylangan edi.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (40, 'Kubernetes noldan: Pod, Deployment va Service', 'Kubernetes''ni o''rganishni boshlaganlar odatda yuzlab obyekt turini ko''rib qo''rqib ketishadi. Aslida kundalik ishning 80 foizi uchta obyekt atrofida aylanadi: **Pod**, **Deployment** va **Service**.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (45, 'PostgreSQL ishlab chiqarishda: indekslar va EXPLAIN ANALYZE', 'Lenta sahifasi 4 soniyada ochilyapti. Sabab deyarli har doim bitta: indekssiz so''rov.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (43, 'Kubernetes noldan: ConfigMap, Secret va health probe''lar', 'Birinchi qismda Deployment va Service yaratdik. Endi ilovani haqiqiy muhitga tayyorlaymiz: konfiguratsiyani image''dan chiqaramiz va Kubernetes''ga ilova "tirikmi" yoki yo''qligini bilishni o''rgatamiz.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (47, 'Kubernetes noldan: Ingress, cert-manager va bepul TLS', 'Service klaster ichida ishlaydi. Foydalanuvchilar esa `https://app.example.uz` orqali kirishi kerak. Buning uchun Ingress controller va avtomatik TLS sertifikat kerak.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (54, 'PostgreSQL ishlab chiqarishda: uzilishsiz migratsiyalar', 'Oddiy ko''ringan `ALTER TABLE users ADD COLUMN ...` bir marta bizning saytimizni 6 daqiqaga to''xtatdi. Migratsiyaning o''zi 50 ms davom etdi. Muammo — lock navbati.
INSERT INTO public.posts (id, title, body, author, category_id, tags, likes, created_at, updated_at, user_id, cover_url, subtitle, slug, status, published_at, reading_time, publish_at, claps, publication_id, canonical_url) VALUES (56, 'Kechasi uyg''otmaydigan alertlar: SLO va burn rate', 'Navbatchi muhandis bir haftada 140 ta alert oldi. Ulardan 6 tasi haqiqiy muammo edi. Qolganlari — "CPU 85%", "disk 70%", "pod restart". Natija: odamlar alertlarni o''qimay qo''yishdi va haqiqiy uzilishni 40 daqiqa kech sezishdi.
